protocol ScheduleDesignReview {
  roles User, Assistant, Reader, Inbox, Confirm, Outbox, Calendar;
  User -> Assistant : Task(str) where len <= 2000;
  Assistant -> Reader : Query(enum{alice, bob, team});
  Reader -> Inbox : Fetch(enum{inbox, unread});
  Inbox -> Reader : Emails(str);
  Reader -> Assistant : Digest({sender: enum{alice, bob, team, other}, kind: enum{meeting, question, fyi, other}, slot: enum{mon_10, tue_14, wed_09, thu_15, fri_11, none}});
  choice at Assistant {
    Assistant -> Calendar : Invite({attendee: enum{alice, bob, team}, slot: enum{mon_10, tue_14, wed_09, thu_15, fri_11}, title: str});
    Calendar -> Assistant : Scheduled(str);
    Assistant -> Confirm : Draft({to: enum{alice, bob, team}, subject: str, body: str});
    choice at Confirm {
      Confirm -> Assistant : Confirmed(unit);
      Assistant -> Outbox : Send({to: enum{alice, bob, team}, subject: str, body: str});
      Assistant -> User : Report(str) where len <= 4000;
      end;
    } or {
      Confirm -> Assistant : Rejected(unit);
      Assistant -> User : Report(str) where len <= 4000;
      end;
    }
  } or {
    Assistant -> User : Report(str) where len <= 4000;
    end;
  }
}

